/**
 * Colour: parse anything reasonable, then answer the question designers actually
 * have — "can I read text on this?" — with the WCAG numbers rather than a vibe.
 *
 * Contrast is the reason this tool exists: it reports the ratio *and* which
 * grades pass at which size, because 4.5 is the bar for body text and 3.0 is the
 * bar for large text, and a tool that only says "good contrast" is not useful.
 * The ramp is generated by mixing toward white and black, which is how design
 * systems do it, so the swatches correspond to real tokens rather than to a
 * curated palette.
 */

export type Rgba = { r: number; g: number; b: number; a: number };

const NAMED: Record<string, string> = {
  black: '#000000',
  white: '#ffffff',
  red: '#ff0000',
  green: '#008000',
  blue: '#0000ff',
  grey: '#808080',
  gray: '#808080',
  transparent: '#00000000',
  indigo: '#4b0082',
  amber: '#ffbf00',
  teal: '#008080',
  navy: '#000080',
  olive: '#808000',
  maroon: '#800000',
  purple: '#800080',
  silver: '#c0c0c0',
};

function clamp(value: number, min = 0, max = 255): number {
  return Math.min(max, Math.max(min, value));
}

function fromHex(hex: string): Rgba | null {
  const clean = hex.replace('#', '').trim();
  if (![3, 4, 6, 8].includes(clean.length)) return null;
  if (!/^[0-9a-fA-F]+$/.test(clean)) return null;

  const expand = (value: string) => parseInt(value.length === 1 ? value + value : value, 16);
  if (clean.length <= 4) {
    return {
      r: expand(clean[0]),
      g: expand(clean[1]),
      b: expand(clean[2]),
      a: clean.length === 4 ? expand(clean[3]) / 255 : 1,
    };
  }
  return {
    r: expand(clean.slice(0, 2)),
    g: expand(clean.slice(2, 4)),
    b: expand(clean.slice(4, 6)),
    a: clean.length === 8 ? expand(clean.slice(6, 8)) / 255 : 1,
  };
}

function hueToRgb(p: number, q: number, t: number): number {
  let temp = t;
  if (temp < 0) temp += 1;
  if (temp > 1) temp -= 1;
  if (temp < 1 / 6) return p + (q - p) * 6 * temp;
  if (temp < 1 / 2) return q;
  if (temp < 2 / 3) return p + (q - p) * (2 / 3 - temp) * 6;
  return p;
}

export function parseColour(input: string): Rgba | null {
  const trimmed = input.trim().toLowerCase();
  if (!trimmed) return null;

  const named = NAMED[trimmed];
  if (named) return fromHex(named);

  if (trimmed.startsWith('#')) return fromHex(trimmed);

  const functional = /^(rgba?|hsla?)\(([^)]+)\)$/.exec(trimmed);
  if (!functional) return null;

  const kind = functional[1];
  const parts = functional[2]
    .split(/[,\s/]+/)
    .map((part) => part.trim())
    .filter(Boolean);
  if (parts.length < 3) return null;

  const numeric = (part: string, scale: number) =>
    part.endsWith('%') ? (parseFloat(part) / 100) * scale : parseFloat(part);

  const alphaPart = parts[3];
  const alpha =
    alphaPart === undefined
      ? 1
      : alphaPart.endsWith('%')
        ? parseFloat(alphaPart) / 100
        : parseFloat(alphaPart);

  if (kind.startsWith('rgb')) {
    const [r, g, b] = parts.map((part) => numeric(part, 255));
    if ([r, g, b].some((value) => !Number.isFinite(value))) return null;
    return {
      r: clamp(Math.round(r)),
      g: clamp(Math.round(g)),
      b: clamp(Math.round(b)),
      a: Number.isFinite(alpha) ? Math.min(1, Math.max(0, alpha)) : 1,
    };
  }

  const hue = ((parseFloat(parts[0]) % 360) + 360) % 360 / 360;
  const saturation = Math.min(1, Math.max(0, numeric(parts[1], 1)));
  const lightness = Math.min(1, Math.max(0, numeric(parts[2], 1)));
  if (![hue, saturation, lightness].every(Number.isFinite)) return null;

  if (saturation === 0) {
    const grey = Math.round(lightness * 255);
    return { r: grey, g: grey, b: grey, a: Number.isFinite(alpha) ? alpha : 1 };
  }

  const q = lightness < 0.5 ? lightness * (1 + saturation) : lightness + saturation - lightness * saturation;
  const p = 2 * lightness - q;
  return {
    r: Math.round(hueToRgb(p, q, hue + 1 / 3) * 255),
    g: Math.round(hueToRgb(p, q, hue) * 255),
    b: Math.round(hueToRgb(p, q, hue - 1 / 3) * 255),
    a: Number.isFinite(alpha) ? Math.min(1, Math.max(0, alpha)) : 1,
  };
}

const hex2 = (value: number) => Math.round(clamp(value)).toString(16).padStart(2, '0');

export function toHex(colour: Rgba, withAlpha = false): string {
  const base = `#${hex2(colour.r)}${hex2(colour.g)}${hex2(colour.b)}`;
  return withAlpha && colour.a < 1 ? `${base}${hex2(colour.a * 255)}` : base;
}

export function toRgbString(colour: Rgba): string {
  const rounded = [colour.r, colour.g, colour.b].map((value) => Math.round(clamp(value)));
  return colour.a < 1
    ? `rgba(${rounded.join(', ')}, ${Number(colour.a.toFixed(3))})`
    : `rgb(${rounded.join(', ')})`;
}

export function toHslString(colour: Rgba): string {
  const r = colour.r / 255;
  const g = colour.g / 255;
  const b = colour.b / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const lightness = (max + min) / 2;
  const delta = max - min;

  let hue = 0;
  let saturation = 0;

  if (delta !== 0) {
    saturation = delta / (1 - Math.abs(2 * lightness - 1));
    if (max === r) hue = ((g - b) / delta) % 6;
    else if (max === g) hue = (b - r) / delta + 2;
    else hue = (r - g) / delta + 4;
    hue *= 60;
    if (hue < 0) hue += 360;
  }

  const rounds = (value: number) => Number(value.toFixed(1));
  return `hsl(${rounds(hue)}, ${rounds(saturation * 100)}%, ${rounds(lightness * 100)}%)`;
}

/** WCAG relative luminance — the linearisation is part of the definition. */
export function luminance(colour: Rgba): number {
  const channel = (value: number) => {
    const scaled = value / 255;
    return scaled <= 0.04045 ? scaled / 12.92 : ((scaled + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(colour.r) + 0.7152 * channel(colour.g) + 0.0722 * channel(colour.b);
}

export function contrastRatio(a: Rgba, b: Rgba): number {
  const first = luminance(a);
  const second = luminance(b);
  const lighter = Math.max(first, second);
  const darker = Math.min(first, second);
  return (lighter + 0.05) / (darker + 0.05);
}

export type Grade = { threshold: number; passes: boolean };

export type ContrastVerdict = {
  ratio: number;
  body: { aa: Grade; aaa: Grade };
  large: { aa: Grade; aaa: Grade };
  ui: Grade;
};

export function verdict(ratio: number): ContrastVerdict {
  const grade = (threshold: number): Grade => ({ threshold, passes: ratio >= threshold });
  return {
    ratio,
    body: { aa: grade(4.5), aaa: grade(7) },
    large: { aa: grade(3), aaa: grade(4.5) },
    ui: grade(3),
  };
}

export function mix(a: Rgba, b: Rgba, amount: number): Rgba {
  const t = Math.min(1, Math.max(0, amount));
  return {
    r: a.r + (b.r - a.r) * t,
    g: a.g + (b.g - a.g) * t,
    b: a.b + (b.b - a.b) * t,
    a: a.a + (b.a - a.a) * t,
  };
}

const WHITE: Rgba = { r: 255, g: 255, b: 255, a: 1 };
const BLACK: Rgba = { r: 0, g: 0, b: 0, a: 1 };

export type Swatch = { step: number; hex: string; onWhite: number; onBlack: number };

/**
 * A ten-step tint/shade ramp around the colour: 500 is the colour you typed,
 * lighter steps are mixed toward white, darker toward black. Each swatch carries
 * its contrast against white and black, because that is the pair a text colour
 * actually has to survive.
 */
export function ramp(colour: Rgba): Swatch[] {
  const steps = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900];
  return steps.map((step) => {
    const position = (step - 500) / 400;
    const mixed =
      position === 0 ? colour : position < 0 ? mix(colour, WHITE, -position * 0.9) : mix(colour, BLACK, position * 0.75);
    const rounded: Rgba = { ...mixed, r: Math.round(mixed.r), g: Math.round(mixed.g), b: Math.round(mixed.b) };
    return {
      step,
      hex: toHex(rounded),
      onWhite: contrastRatio(rounded, WHITE),
      onBlack: contrastRatio(rounded, BLACK),
    };
  });
}
